// EDITAR UNA VEZ tras importar: valores del despliegue que NO son secretos.
// Las claves privadas (GitHub, Claude, clave de servicio de Supabase, Gmail) van en credenciales de n8n, nunca aquí.
return [{ json: {
  github_repo: 'silviagomessgm-oss/meridiano-motor',
  github_rama: 'main',
  supabase_url: 'https://vxvmgwlrtrhqjuacmdss.supabase.co',
  hoja_datos_id: '1qXWmguY7LEdKcJPN2aKaWtKEmj9cY_l7SGqDC9-V_ko',
  panel_url: 'https://meridiano-press.lovable.app',
  correo_direccion: 'direccion@meridiano.com',
  correo_datos: 'datos@meridiano.com',
  modelo_ia: 'claude-sonnet-5-5',
  modo_demo: true,
  buzon_demo: 'meridiano.pres@gmail.com',
} }];

// Flujo de los lunes: la fecha de la semana es el lunes de hoy (si se ejecuta otro día, el lunes de esta semana).
// Para una ejecución manual de prueba, cambiar por: return [{ json: { fecha: '2026-11-02' } }];
const ahora = new Date(new Date().toLocaleString('en-US', { timeZone: 'Europe/Madrid' }));
const atras = (ahora.getDay() + 6) % 7;                         // 0 si hoy es lunes
const lunes = new Date(Date.UTC(ahora.getFullYear(), ahora.getMonth(), ahora.getDate() - atras));
return [{ json: { fecha: lunes.toISOString().slice(0, 10) } }];

// Respuesta de preparar_lunes(): una propuesta por item para que la IA redacte cada material por separado.
// Acepta las formas en que n8n puede entregar la respuesta (un item con el array entero, o un item por fila) y la
// forma { preparar_lunes: {...} } de PostgREST. Si Supabase devuelve un error, el flujo se detiene con el mensaje.
const filas = [];
for (const it of $input.all()) {
  const r = it.json || {};
  if ((r.statusCode || 200) >= 300) {
    const b = r.body || {};
    throw new Error('Supabase no ha podido preparar las propuestas del lunes: ' + (b.message || JSON.stringify(b)).slice(0, 300));
  }
  const cuerpo = 'body' in r ? r.body : r;
  for (const x of (Array.isArray(cuerpo) ? cuerpo : [cuerpo])) {
    const p = x && x.preparar_lunes ? x.preparar_lunes : x;
    if (p && p.id) filas.push(p);
  }
}
if (!filas.length) {
  // Sin propuestas: se deja constancia en la salida para que se vea en n8n por qué no sigue
  return [{ json: { sin_propuestas: true, aviso: 'preparar_lunes no ha devuelto propuestas: no hay leads nuevos ni clientes candidatos a ampliación, o ya se prepararon y redactaron esta semana', respuesta: $input.first().json } }];
}
return filas.map(p => ({ json: p }));

// Sensor de Govern para el material del lunes (mismas reglas que en el churn):
//  1. toda cifra del borrador debe aparecer en el contexto enviado a la IA;
//  2. ninguna condición económica (porcentajes, precios, descuento, rebaja, gratis);
//  3. máximo 200 palabras.
// Si falla cualquier regla o la IA no responde, se conserva la plantilla y se anota el motivo.
const propuestas = $('¿Hay propuestas?').all();
const numeros = s => new Set(String(s || '').match(/\d+(?:[.,]\d+)?/g) || []);
return $input.all().map((it, i) => {
  const p = propuestas[i].json;
  const r = it.json || {};
  const texto = Array.isArray(r.content)
    ? r.content.filter(c => c.type === 'text').map(c => c.text).join('\n').trim() : '';
  const motivos = [];
  if (!texto) motivos.push('IA no disponible' + (r.error ? ` (${String(r.error.message || r.error).slice(0, 80)})` : ''));
  else {
    const ctx = numeros(p.contexto_ia);
    const inventadas = [...numeros(texto)].filter(n => !ctx.has(n)).sort();
    if (inventadas.length) motivos.push(`cifras no trazables [${inventadas.join(', ')}]`);
    if (/\d+\s*%|€|euros?\b|descuento|rebaja|gratis/i.test(texto)) motivos.push('condición económica');
    const palabras = texto.split(/\s+/).filter(Boolean).length;
    if (palabras > 200) motivos.push(`${palabras} palabras`);
  }
  const ok = motivos.length === 0;
  return { json: {
    id: p.id, fecha_corte: p.fecha_corte, etiqueta: p.etiqueta, razon_social: p.razon_social,
    comercial_asignado: p.comercial_asignado,
    material_cuerpo: ok ? texto : p.material_cuerpo,
    fuente_material: ok ? 'llm' : `plantilla (IA descartada: ${motivos.join('; ')})`,
    valido: ok,
  } };
});

// Registro de la preparación de los lunes en la tabla ejecuciones (trazabilidad para Govern).
const filas = $('Validador del lunes').all().map(i => i.json);
const llm = filas.filter(f => f.valido).length;
const por = e => filas.filter(f => f.etiqueta === e).length;
return [{ json: { origen: 'n8n', estado: 'ok', detalle: {
  flujo: 'W4', fecha: filas[0]?.fecha_corte, propuestas: filas.length, ampliacion: por('ampliacion'), lead_nuevo: por('lead_nuevo'),
  material_ia: llm, material_plantilla: filas.length - llm,
  descartes: filas.filter(f => !f.valido).map(f => ({ id: f.id, motivo: f.fuente_material })),
} } }];

// H7 · Puerta de datos: solo se sigue si la última carga de W0 terminó bien hace menos de 8 días (ultima_carga() en Supabase).
// Si Supabase no responde, tampoco se sigue: mejor no generar propuestas que generarlas con datos viejos.
const r = $input.first().json || {};
const c = (r.body && typeof r.body === 'object') ? r.body : {};
const ok = r.statusCode >= 200 && r.statusCode < 300 && c.apta === true;
return ok ? $('Fecha del lunes').all() : [];

// H7 · Si la carga de datos no es válida: aviso a dirección y al responsable de datos, y registro en ejecuciones.
const r = $input.first().json || {};
const c = (r.body && typeof r.body === 'object') ? r.body : {};
if (r.statusCode >= 200 && r.statusCode < 300 && c.apta === true) return [];
const cfg = $('Configuración').first().json;
const flujo = (typeof $workflow !== 'undefined' && $workflow.name) || 'Meridiano';
const motivo = c.motivo || `no se ha podido consultar el estado de la carga (Supabase: ${r.statusCode || 'sin respuesta'})`;
return [{ json: {
  para: [cfg.correo_direccion, cfg.correo_datos].filter(Boolean).join(','),
  asunto: 'Meridiano · ciclo detenido: los datos no están al día',
  texto: `${flujo} no ha generado propuestas porque ${motivo}.\n\n` +
    (c.fecha ? `Última carga registrada: ${String(c.fecha).slice(0, 16).replace('T', ' ')} (${c.estado}).\n\n` : '') +
    'Revise la hoja de datos y lance W0 («Cargar ahora»); después vuelva a ejecutar este flujo a mano. ' +
    'El panel conserva el plan de la semana anterior.',
  registro: { origen: 'n8n', estado: 'detenido_por_datos', detalle: { flujo: flujo, motivo, ultima_carga: c } },
} }];
